import math

def isPrime(x):
    """Returns 1 if x is prime, 0 otherwise"""
    if x < 2:
        return 0             # not prime
    if x == 2:
        return 1             # 2 is prime
    if x % 2 == 0:
        return 0             # even numbers not prime
    # Check odd divisors up to sqrt(x)
    for d in range(3, int(math.sqrt(x)) + 1, 2):
        if x % d == 0:
            return 0         # divisible, not prime
    return 1

# Find first 50 prime numbers
primeNumbers = []            # empty list
n = 2                        # start from 2

while len(primeNumbers) < 50:
    if isPrime(n) == 1:
        primeNumbers.append(n)   # add prime to list
    n += 1

# Display the prime numbers
print('First 50 prime numbers:')
for k, p in enumerate(primeNumbers):
    print(f'{p:4d}', end='')
    if (k + 1) % 10 == 0:
        print()              # new line every 10 numbers

