    % Input: x — non-negative integer
    % Output: y — x!

    % Validate: check for negative input
    if x < 0
        error('Error: factorial is not defined for negative numbers.');
    end

    % Validate: check for non-integer input
    if x ~= floor(x)
        error('Error: factorial is not defined for non-integer numbers.');
    end

    % Special case: 0! = 1
    if x == 0
        y = 1;
        return;
    end

    % Calculate factorial using a for loop
    y = 1;
    for i = 1:x
        y = y * i;   % multiply by each integer up to x
    end
