def fact(x):
    """Calculates factorial of x without using built-in factorial"""

    # Validate: check for negative input
    if x < 0:
        raise ValueError('Error: factorial is not defined for negative numbers.')

    # Validate: check for non-integer input
    if x != int(x):
        raise ValueError('Error: factorial is not defined for non-integer numbers.')

    x = int(x)   # convert to integer type

    # Special case: 0! = 1
    if x == 0:
        return 1

    # Calculate factorial using a loop
    y = 1
    for i in range(1, x + 1):
        y = y * i   # multiply by each integer up to x
    return y

# Test the function
print(f'0! = {fact(0)}')
print(f'5! = {fact(5)}')
print(f'10! = {fact(10)}')

# Test error handling
try:
    fact(-3)
except ValueError as e:
    print('Caught:', e)

try:
    fact(2.5)
except ValueError as e:
    print('Caught:', e)

