% Cam mechanism displacement profile

% Create theta vector with 500 elements from 0 to 2*pi
theta = linspace(0, 2*pi, 500);
y = zeros(1, 500);   % initialize displacement array

% Calculate y for each theta using loop and conditionals
for k = 1:500
    t = theta(k);   % current theta value

    if t >= 0 && t < pi/2
        % Region 1: rising
        y(k) = 6 * (2*t - 0.5*sin(t)) / pi;

    elseif t >= pi/2 && t < 2*pi/3
        % Region 2: constant at maximum
        y(k) = 6;

    elseif t >= 2*pi/3 && t < 4*pi/3
        % Region 3: falling
        y(k) = 6 - 3*(1 - 0.5*cos(3*(t - 2*pi/3)));

    elseif t >= 4*pi/3 && t < 3*pi/2
        % Region 4: continued fall (parabolic)
        y(k) = 3 - 1.5*((t - 3*pi/2)/(pi/4))^2;

    elseif t >= 3*pi/2 && t < 7*pi/4
        % Region 5: at rest (zero displacement)
        y(k) = 0;

    else
        % Region 6: rising back (7*pi/4 to 2*pi)
        y(k) = 0.75 - 0.75*(1 - (t - 7*pi/4)/(pi/4))^2;
    end
