% Polyadd function — adds or subtracts two polynomials
function P = Polyadd(P1, P2, operation)
    % Input: P1, P2 — coefficient vectors (descending order)
    %        operation — 'add' or 'sub'
    % Output: P — resulting polynomial coefficients

    n1 = length(P1);   % length of first polynomial
    n2 = length(P2);   % length of second polynomial

    % Zero-pad shorter polynomial to match lengths
    if n1 > n2
        P2 = [zeros(1, n1-n2), P2];   % pad P2 with zeros at front
    elseif n2 > n1
        P1 = [zeros(1, n2-n1), P1];   % pad P1 with zeros at front
    end

    % Perform addition or subtraction
    if strcmp(operation, 'add')
        P = P1 + P2;       % element-wise addition
    elseif strcmp(operation, 'sub')
        P = P1 - P2;       % element-wise subtraction
    else
        error('operation must be add or sub');
    end
endfunction

% Define the two polynomials
% f1(x) = 2x^6 - 3x^4 - 9x^3 + 11x^2 - 8x + 4
P1 = [2, 0, -3, -9, 11, -8, 4];

% f2(x) = 5x^3 + 7x - 10
P2 = [5, 0, 7, -10];

% Perform addition
P_sum = Polyadd(P1, P2, 'add');
fprintf('f1 + f2 = ');
fprintf('%g ', P_sum);
fprintf('\n');

% Perform subtraction
P_diff = Polyadd(P1, P2, 'sub');
fprintf('f1 - f2 = ');
fprintf('%g ', P_diff);
fprintf('\n');

% Verify using polyval at x=1
x_test = 1;
f1_val = polyval(P1, x_test);
f2_val = polyval(P2, x_test);
fprintf('\nVerification at x=1: f1=%g, f2=%g\n', f1_val, f2_val);
fprintf('f1+f2=%g, Polyadd result=%g\n', f1_val+f2_val, polyval(P_sum, x_test));
fprintf('f1-f2=%g, Polyadd result=%g\n', f1_val-f2_val, polyval(P_diff, x_test));
